/* Values are integer øre. Math is kept independent of the interface for parity tests. */
(function(root){
'use strict';
const round=v=>Math.round(v+1e-7);
function money(v,label){if(v===''||v===null||v===undefined||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>1e7||Math.abs(Number(v)*100-round(Number(v)*100))>1e-5)throw Error(label+' skal være et positivt beløb eller 0, med højst to decimaler.');return round(Number(v)*100);}
function month(v){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(v)||Number(v.slice(0,4))<1)throw Error('Vælg gyldige måneder.');return Number(v.slice(0,4))*12+Number(v.slice(5))-1;}
function date(v){return String(Math.floor(v/12)).padStart(4,'0')+'-'+String(v%12+1).padStart(2,'0');}
function study(debt,loan,start,end){let balance=debt;const rows=[];for(let i=start;i<=end;i++){let interest=round((balance+loan)/300);balance+=loan+interest;rows.push({month:date(i),debt:balance,interest,payment:0,fee:0});}return {rows,debt:balance,borrowed:loan*rows.length,interest:rows.reduce((s,r)=>s+r.interest,0)};}
function repay(debt,end,percent,interval){let balance=debt;const rows=[],first=(Math.floor(end/12)+2)*12,rate=percent/1200;for(let i=end+1;i<first;i++){const interest=round(balance*rate);balance+=interest;rows.push({month:date(i),debt:balance,interest,payment:0,fee:0});}const opening=balance,years=Math.min(15,7+Math.max(0,Math.floor(balance/2000000)-1)),count=years*12/interval;let discount=0;for(let k=0;k<count;k++)discount+=(1+rate)**-(1+k*interval);const regular=balance?Math.max(20000,Math.ceil(balance/discount-1e-7)):0;for(let o=0;o<years*12&&balance;o++){let interest=round(balance*rate);balance+=interest;let payment=0,fee=0;if(o%interval===0){payment=o===(count-1)*interval?balance:Math.min(regular,balance);balance-=payment;fee=1500;}rows.push({month:date(first+o),debt:balance,interest,payment,fee});}const payments=rows.filter(r=>r.payment);return {rows,opening,years,regular,start:payments.length?date(first):null,end:payments.length?payments.at(-1).month:null,waitInterest:opening-debt,interest:rows.reduce((s,r)=>s+r.interest,0),fees:payments.reduce((s,r)=>s+r.fee,0),total:payments.reduce((s,r)=>s+r.payment+r.fee,0),maxPayment:Math.max(0,...payments.map(r=>r.payment+r.fee))};}
function calculate(input){const loan=money(input.loan,'Lånet'),debt=money(input.debt,'Gælden'),start=month(input.start),end=month(input.end),rate=money(input.rate,'Renten')/100,interval=Number(input.interval);if(loan>379900)throw Error('Almindeligt SU-lån er begrænset til 3.799 kr. i dette scenarie.');if(end<start||end-start>=600)throw Error('Slutmåneden skal være efter eller lig startmåneden. Perioden må højst være 600 måneder.');if(rate>100)throw Error('Renten skal være mellem 0 og 100 %.');if(![1,2].includes(interval))throw Error('Vælg betaling hver eller hver anden måned.');const result=study(debt,loan,start,end),lower=study(debt,Math.max(0,loan-50000),start,end),payment=repay(result.debt,end,rate,interval);let budget=null;const hasNet=input.net!==''&&input.net!==undefined,hasExpenses=input.expenses!==''&&input.expenses!==undefined;if(hasNet!==hasExpenses)throw Error('Udfyld både indkomst og udgifter, eller lad begge være tomme.');if(hasNet){const net=money(input.net,'Indkomsten'),expenses=money(input.expenses,'Udgifterne'),reserve=payment.maxPayment/interval;budget={net,expenses,reserve,left:net-expenses-reserve,cash:net-expenses-payment.maxPayment};}return {input:{...input},study:result,lower,payment,budget,interval,rate,start:input.start,end:input.end};}
root.SU={calculate};if(typeof module!=='undefined')module.exports={calculate};
})(typeof globalThis!=='undefined'?globalThis:this);
